function MiniFeature({ icon, title, body }: { icon: ReactNode; title: string; body: string }) { return <div className="rounded-2xl border border-border bg-card p-5"><div className="mb-5 text-primary">{icon}</div><h3 className="font-semibold">{title}</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">{body}</p></div>; }

function AuthLayout({ children, heading, body }: { children: ReactNode; heading: string; body: string }) {
  return <div className="grid min-h-[100dvh] bg-background lg:grid-cols-[.9fr_1.1fr]"><div className="grid-paper relative hidden overflow-hidden bg-foreground p-10 text-background lg:flex lg:flex-col lg:justify-between"><Link href="/" className="flex items-center gap-2" data-testid="link-auth-brand"><span className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-primary-foreground"><Sparkles className="h-4 w-4" /></span><span className="display-font text-xl">CampusPulse</span></Link><div className="relative max-w-md"><p className="mono-font mb-4 text-xs uppercase tracking-[.2em] text-primary">A place to belong</p><p className="display-font text-6xl leading-[.95]">Your next<br /><span className="text-primary">chapter</span> starts here.</p><p className="mt-6 max-w-sm text-sm leading-7 text-background/65">The best parts of campus are rarely on the syllabus. Find them, join them, make them yours.</p></div><p className="text-xs text-background/45">CampusPulse · participation, made human.</p></div><div className="flex flex-col p-5 md:p-10"><Link href="/" className="mb-12 flex items-center gap-2 lg:hidden" data-testid="link-auth-mobile-brand"><span className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-primary-foreground"><Sparkles className="h-4 w-4" /></span><span className="display-font text-xl">CampusPulse</span></Link><div className="m-auto w-full max-w-md animate-pulse-in"><p className="mono-font text-xs uppercase tracking-[.2em] text-primary">Welcome in</p><h1 className="display-font mt-3 text-4xl tracking-tight">{heading}</h1><p className="mt-3 text-sm leading-6 text-muted-foreground">{body}</p><div className="mt-8">{children}</div></div></div></div>;
}
function LoginPage() {
  const [, setLocation] = useLocation(); const login = useLoginUser(); const [form, setForm] = useState({ email: '', password: '' }); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); login.mutate({ data: form }, { onSuccess: (result) => { localStorage.setItem('campuspulse_access', result.access); if (result.refresh) localStorage.setItem('campuspulse_refresh', result.refresh); queryClient.setQueryData(getGetCurrentUserQueryKey(), result.user); setLocation('/dashboard'); }, onError: () => setError('Those details did not match. Try again or create a new profile.') }); };
  return <AuthLayout heading="Good to see you." body="Sign in to pick up where you left off."><form onSubmit={submit} className="space-y-5"><Field label="Campus email" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} placeholder="you@campus.edu" testId="input-email" /><Field label="Password" type="password" value={form.password} onChange={(value) => setForm({ ...form, password: value })} placeholder="At least 8 characters" testId="input-password" />{error && <p className="rounded-xl bg-destructive/10 p-3 text-sm text-destructive" data-testid="status-login-error">{error}</p>}<button disabled={login.isPending} className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground hover:-translate-y-0.5 disabled:opacity-60" data-testid="button-login">{login.isPending && <Loader2 className="h-4 w-4 animate-spin" />}Sign in</button><p className="text-center text-sm text-muted-foreground">New to the community? <Link href="/register" className="font-semibold text-primary" data-testid="link-create-account">Create a profile</Link></p></form></AuthLayout>;
}
function RegisterPage() {
  const [, setLocation] = useLocation(); const register = useRegisterUser(); const [form, setForm] = useState({ name: '', email: '', password: '' }); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); register.mutate({ data: form }, { onSuccess: (result) => { localStorage.setItem('campuspulse_access', result.access); if (result.refresh) localStorage.setItem('campuspulse_refresh', result.refresh); queryClient.setQueryData(getGetCurrentUserQueryKey(), result.user); setLocation('/dashboard'); }, onError: () => setError('We could not create that profile. Check your details and try once more.') }); };
  return <AuthLayout heading="Make room for more." body="A student profile keeps your registrations in one place. It takes less than a minute."><form onSubmit={submit} className="space-y-5"><Field label="Your name" value={form.name} onChange={(value) => setForm({ ...form, name: value })} placeholder="How should we call you?" testId="input-name" /><Field label="Campus email" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} placeholder="you@campus.edu" testId="input-email" /><Field label="Password" type="password" value={form.password} onChange={(value) => setForm({ ...form, password: value })} placeholder="8+ characters" testId="input-password" />{error && <p className="rounded-xl bg-destructive/10 p-3 text-sm text-destructive" data-testid="status-register-error">{error}</p>}<button disabled={register.isPending} className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground hover:-translate-y-0.5" data-testid="button-register">{register.isPending && <Loader2 className="h-4 w-4 animate-spin" />}Create my profile</button><p className="text-center text-sm text-muted-foreground">Already have a profile? <Link href="/login" className="font-semibold text-primary" data-testid="link-sign-in">Sign in</Link></p></form></AuthLayout>;
}
function Field({ label, value, onChange, type = 'text', placeholder, testId }: { label: string; value: string; onChange: (value: string) => void; type?: string; placeholder?: string; testId: string }) {
  return <label className="block space-y-2"><span className="text-sm font-semibold">{label}</span><input data-testid={testId} type={type} required value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} className="w-full rounded-xl border border-input bg-card px-4 py-3 text-sm outline-none placeholder:text-muted-foreground/60 focus:border-primary focus:ring-2 focus:ring-primary/15" /></label>;
}

function AppShell({ children, user }: { children: ReactNode; user: User }) {
  const [location, setLocation] = useLocation(); const [mobileOpen, setMobileOpen] = useState(false);
  const logout = () => { localStorage.removeItem('campuspulse_access'); localStorage.removeItem('campuspulse_refresh'); queryClient.clear(); setLocation('/'); };
  const links = user.role === 'ADMIN' ? [{ href: '/dashboard', label: 'Overview', icon: LayoutDashboard }, { href: '/admin/events', label: 'Events', icon: CalendarDays }, { href: '/admin/registrations', label: 'Registrations', icon: ListChecks }, { href: '/admin/categories', label: 'Categories', icon: Tags }] : [{ href: '/dashboard', label: 'My pulse', icon: LayoutDashboard }, { href: '/events', label: 'Discover events', icon: CalendarDays }, { href: '/my-registrations', label: 'My registrations', icon: Ticket }];
  return <div className="min-h-[100dvh] bg-background"><aside className={cx('fixed inset-y-0 left-0 z-40 flex w-64 flex-col bg-sidebar p-5 text-sidebar-foreground transition-transform md:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}><Link href="/dashboard" className="flex items-center gap-2.5 px-2" data-testid="link-shell-brand"><span className="grid h-9 w-9 place-items-center rounded-xl bg-sidebar-primary text-sidebar-primary-foreground"><Sparkles className="h-4 w-4" /></span><span className="display-font text-xl">CampusPulse</span></Link><div className="mt-12 flex-1 space-y-1">{links.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileOpen(false)} className={cx('flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground', location.startsWith(href) && 'bg-sidebar-accent text-sidebar-foreground')} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon className="h-4 w-4" />{label}</Link>)}{user.role === 'ADMIN' && <div className="mt-8 border-t border-sidebar-border pt-5"><p className="mono-font mb-2 px-3 text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/35">Workspace</p><Link href="/admin/events/new" className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="link-nav-create-event"><Plus className="h-4 w-4" />Create event</Link></div>}</div><div className="border-t border-sidebar-border pt-4"><Link href="/profile" className="flex items-center gap-3 rounded-xl p-2 hover:bg-sidebar-accent" data-testid="link-profile"><Avatar user={user} size="sm" /><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{user.name}</span><span className="block text-[11px] text-sidebar-foreground/45">{user.role === 'ADMIN' ? 'Coordinator' : 'Student'}</span></span></Link><button onClick={logout} className="mt-2 flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm text-sidebar-foreground/50 hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid="button-logout"><LogOut className="h-4 w-4" />Sign out</button></div></aside><div className="md:pl-64"><header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur-md md:px-8"><button onClick={() => setMobileOpen(!mobileOpen)} className="rounded-lg p-2 md:hidden" data-testid="button-menu"><Menu className="h-5 w-5" /></button><div className="hidden text-sm text-muted-foreground md:block">{user.role === 'ADMIN' ? 'Coordinator workspace' : 'Your campus, your rhythm'}</div><div className="flex items-center gap-3"><Link href="/profile" className="text-right" data-testid="link-header-profile"><span className="block text-sm font-semibold">{user.name}</span><span className="block text-[11px] text-muted-foreground">{user.email}</span></Link><Avatar user={user} /></div></header><main className="mx-auto max-w-7xl px-5 py-8 md:px-8 md:py-10">{children}</main></div></div>;
}
function Protected({ children, admin = false }: { children: ReactNode; admin?: boolean }) {
  const [, setLocation] = useLocation(); const auth = useAuthUser(); const refresh = useRefreshToken();
  useEffect(() => {
    const refreshValue = localStorage.getItem('campuspulse_refresh');
    if (auth.isError && refreshValue && !refresh.isPending) {
      refresh.mutate({ data: { refresh: refreshValue } }, {
        onSuccess: (result) => {
          localStorage.setItem('campuspulse_access', result.access);
          if (result.refresh) localStorage.setItem('campuspulse_refresh', result.refresh);
          queryClient.invalidateQueries({ queryKey: getGetCurrentUserQueryKey() });
        },
        onError: () => localStorage.removeItem('campuspulse_refresh'),
      });
    }
  }, [auth.isError]);
  useEffect(() => { if (!getToken()) setLocation('/login'); else if (!auth.isLoading && auth.data && admin && auth.data.role !== 'ADMIN') setLocation('/dashboard'); }, [auth.data, auth.isLoading, admin, setLocation]);
  if (!getToken() || auth.isLoading) return <div className="min-h-[100dvh] bg-background p-5"><LoadingBlock label="Checking your access" /></div>;
  if (auth.isError && (refresh.isPending || localStorage.getItem('campuspulse_refresh'))) return <div className="min-h-[100dvh] bg-background p-5"><LoadingBlock label="Refreshing your session" /></div>;
  if (auth.isError) return <div className="min-h-[100dvh] bg-background p-5"><ErrorBlock message="Your session has expired." onRetry={() => setLocation('/login')} /></div>;
  return auth.data ? <AppShell user={auth.data}>{children}</AppShell> : null;
}

function StatCard({ label, value, detail, icon: Icon, accent = false }: { label: string; value: number | string; detail: string; icon: typeof CalendarDays; accent?: boolean }) {
  return <div className={cx('rounded-2xl border border-border p-5', accent ? 'bg-primary text-primary-foreground' : 'bg-card')}><div className="flex items-start justify-between"><div><p className={cx('text-xs font-semibold uppercase tracking-widest', accent ? 'text-primary-foreground/65' : 'text-muted-foreground')}>{label}</p><p className="display-font mt-3 text-4xl" data-testid={`text-stat-${label.toLowerCase().replaceAll(' ', '-')}`}>{value}</p></div><span className={cx('rounded-xl p-2.5', accent ? 'bg-primary-foreground/15' : 'bg-muted text-primary')}><Icon className="h-5 w-5" /></span></div><p className={cx('mt-5 text-xs', accent ? 'text-primary-foreground/70' : 'text-muted-foreground')}>{detail}</p></div>;
}
function DashboardPage() {
  const auth = useAuthUser(); const user = auth.data; const stats = useGetDashboardStats({ query: { queryKey: getGetDashboardStatsQueryKey() } });
  const isAdmin = user?.role === 'ADMIN';
  if (!user || stats.isLoading) return <LoadingBlock />;
  if (stats.isError) return <ErrorBlock onRetry={() => stats.refetch()} />;
  const data = stats.data; const recent = data?.recent_events ?? [];
  return <><PageTitle eyebrow={isAdmin ? 'Coordinator desk' : 'Good morning'} title={isAdmin ? 'Keep campus moving.' : `Welcome back, ${user.name.split(' ')[0]}.`} body={isAdmin ? 'A clear view of what is happening, what needs attention, and who is showing up.' : 'The right event is usually one small yes away.'} action={!isAdmin && <Link href="/events" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground" data-testid="link-dashboard-discover">Find an event <ArrowRight className="h-4 w-4" /></Link>} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatCard label="Upcoming events" value={data?.upcoming_events ?? 0} detail={isAdmin ? `${data?.total_events ?? 0} total in the calendar` : `${data?.available_events ?? 0} open to join`} icon={CalendarDays} accent /><StatCard label={isAdmin ? 'Students reached' : 'My registrations'} value={isAdmin ? data?.total_students ?? 0 : data?.my_registrations ?? 0} detail={isAdmin ? 'Active campus profiles' : 'A month with range'} icon={Users} /><StatCard label="Completed" value={data?.completed_events ?? 0} detail="Moments already made" icon={Check} /><StatCard label="Registrations" value={data?.total_registrations ?? 0} detail={isAdmin ? 'Across all events' : 'Community momentum'} icon={Ticket} /></div><div className="mt-10 grid gap-8 lg:grid-cols-[1.3fr_.7fr]"><section><div className="mb-4 flex items-center justify-between"><h2 className="display-font text-2xl">Recent on campus</h2><Link href={isAdmin ? '/admin/events' : '/events'} className="text-sm font-semibold text-primary" data-testid="link-dashboard-events">View all</Link></div>{recent.length ? <div className="space-y-3">{recent.slice(0, 5).map((event) => <CompactEvent event={event} key={event.id} />)}</div> : <EmptyBlock title="The calendar is waking up." body="New events will appear here when they are published." action={<Link href="/events" className="font-semibold text-primary" data-testid="link-empty-events">Browse the directory</Link>} />}</section><section className="rounded-2xl bg-foreground p-6 text-background"><p className="mono-font text-[10px] uppercase tracking-[.2em] text-primary">A small nudge</p><h2 className="display-font mt-4 text-3xl">Show up for something you did not plan.</h2><p className="mt-4 text-sm leading-6 text-background/60">Campus is bigger than your timetable. Keep one evening open.</p><Link href="/events" className="mt-8 inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground" data-testid="link-dashboard-nudge">Explore the calendar <ArrowRight className="h-4 w-4" /></Link></section></div></>;
}
function CompactEvent({ event }: { event: Event }) { return <Link href={`/events/${event.id}`} className="group flex items-center gap-4 rounded-2xl border border-border bg-card p-4 hover:-translate-y-0.5 hover:border-primary" data-testid={`card-event-${event.id}`}><div className="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-primary/10 text-center text-primary"><span className="block text-[10px] font-bold uppercase">{new Date(`${event.date}T12:00:00`).toLocaleDateString('en-US', { month: 'short' })}</span><span className="display-font block text-xl leading-4">{new Date(`${event.date}T12:00:00`).getDate()}</span></div><div className="min-w-0 flex-1"><p className="truncate font-semibold group-hover:text-primary">{event.title}</p><p className="mt-1 flex items-center gap-2 text-xs text-muted-foreground"><span>{event.category.name}</span><span>·</span><span>{event.venue}</span></p></div><Badge tone={event.status === 'CANCELLED' ? 'red' : 'teal'}>{event.status}</Badge></Link>; }

function EventCard({ event, dark = false, index = 0 }: { event: Event; dark?: boolean; index?: number }) {
  return <Link href={`/events/${event.id}`} className={cx('group relative block overflow-hidden rounded-2xl border p-5 transition-transform hover:-translate-y-1', dark ? 'border-background/15 bg-background/10 text-background' : 'border-border bg-card', index === 1 && 'md:translate-y-6')} data-testid={`card-event-directory-${event.id}`}><div className="flex items-start justify-between gap-3"><span className={cx('rounded-lg p-2', dark ? 'bg-primary/20 text-primary' : 'bg-primary/10 text-primary')}><CalendarDays className="h-5 w-5" /></span><Badge tone={event.status === 'CANCELLED' ? 'red' : 'teal'}>{event.status}</Badge></div><p className={cx('mono-font mt-8 text-[10px] uppercase tracking-[.18em]', dark ? 'text-background/50' : 'text-muted-foreground')}>{event.category.name}</p><h3 className="display-font mt-2 line-clamp-2 text-2xl leading-tight">{event.title}</h3><div className={cx('mt-8 space-y-2 border-t pt-4 text-xs', dark ? 'border-background/15 text-background/60' : 'border-border text-muted-foreground')}><p className="flex items-center gap-2"><Clock3 className="h-3.5 w-3.5" />{dateLabel(event.date)} · {timeLabel(event.start_time)}</p><p className="flex items-center gap-2"><MapPin className="h-3.5 w-3.5" />{event.venue}</p></div></Link>;
}

function EventsPage() {
  const [location] = useLocation(); const initialCategory = new URLSearchParams(location.split('?')[1] ?? '').get('category') ?? '';
  const [search, setSearch] = useState(''); const [category, setCategory] = useState(initialCategory); const [status, setStatus] = useState(''); const categories = useListCategories();
  const params = useMemo(() => ({ search: search || undefined, category: category ? Number(category) : undefined, status: (status || undefined) as EventStatus | undefined, ordering: 'date' as const }), [search, category, status]);
  const events = useListEvents(params, { query: { queryKey: getListEventsQueryKey(params) } });
  return <><PageTitle eyebrow="The directory" title="What is happening?" body="Search by a feeling, a place, or a category. There is more to campus than one schedule." /><div className="mb-8 grid gap-3 rounded-2xl border border-border bg-card p-3 md:grid-cols-[1fr_180px_160px]"><label className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search events" className="h-10 w-full rounded-xl bg-muted pl-10 pr-3 text-sm outline-none focus:ring-2 focus:ring-primary/20" data-testid="input-event-search" /></label><select value={category} onChange={(e) => setCategory(e.target.value)} className="h-10 rounded-xl bg-muted px-3 text-sm outline-none" data-testid="select-event-category"><option value="">All categories</option>{(categories.data ?? []).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><select value={status} onChange={(e) => setStatus(e.target.value)} className="h-10 rounded-xl bg-muted px-3 text-sm outline-none" data-testid="select-event-status"><option value="">All statuses</option><option value="UPCOMING">Upcoming</option><option value="ONGOING">Ongoing</option><option value="COMPLETED">Completed</option></select></div>{events.isLoading ? <LoadingBlock /> : events.isError ? <ErrorBlock onRetry={() => events.refetch()} /> : events.data?.length ? <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{events.data.map((event, index) => <EventCard key={event.id} event={event} index={index} />)}</div> : <EmptyBlock title="No events match that search." body="Try a broader search, or clear the filters to see the full campus calendar." action={<button onClick={() => { setSearch(''); setCategory(''); setStatus(''); }} className="font-semibold text-primary" data-testid="button-clear-filters">Clear filters</button>} />}</>;
}

function EventDetailsPage() {
  const { id } = useParams<{ id: string }>(); const eventId = Number(id); const event = useGetEvent(eventId, { query: { queryKey: getGetEventQueryKey(eventId) } }); const register = useRegisterForEvent(); const auth = useAuthUser(); const [, setLocation] = useLocation(); const [registered, setRegistered] = useState(false); const [message, setMessage] = useState('');
  if (event.isLoading) return <LoadingBlock />; if (event.isError || !event.data) return <ErrorBlock message="That event could not be found." />; const item = event.data;
  const join = () => { if (!getToken()) { setLocation('/login'); return; } register.mutate({ id: item.id }, { onSuccess: () => { setRegistered(true); setMessage('You are on the list. See you there.'); queryClient.invalidateQueries({ queryKey: getGetEventQueryKey(item.id) }); queryClient.invalidateQueries({ queryKey: getListMyRegistrationsQueryKey() }); }, onError: () => setMessage('Registration is currently unavailable. Please try again.') }); };
  return <div className="mx-auto max-w-5xl"><Link href="/events" className="mb-8 inline-flex items-center gap-2 text-sm font-semibold text-primary" data-testid="link-back-events"><ArrowRight className="h-4 w-4 rotate-180" />Back to events</Link><div className="grid gap-8 lg:grid-cols-[1.3fr_.7fr]"><article className="rounded-3xl bg-foreground p-7 text-background md:p-10"><div className="flex items-start justify-between gap-4"><Badge tone="teal">{item.category.name}</Badge><Badge tone={item.status === 'CANCELLED' ? 'red' : 'teal'}>{item.status}</Badge></div><h1 className="display-font mt-10 max-w-3xl text-5xl leading-[.98] tracking-tight md:text-7xl">{item.title}</h1><p className="mt-7 max-w-2xl whitespace-pre-wrap text-sm leading-7 text-background/65">{item.description}</p><div className="mt-12 grid gap-5 border-t border-background/15 pt-6 sm:grid-cols-2"><Detail icon={<CalendarDays />} label="When" value={`${dateLabel(item.date)} · ${timeLabel(item.start_time)}–${timeLabel(item.end_time)}`} dark /><Detail icon={<MapPin />} label="Where" value={item.venue} dark /><Detail icon={<Users />} label="Capacity" value={`${item.participant_count} of ${item.capacity} spots taken`} dark /><Detail icon={<UserRound />} label="Hosted by" value={item.organizer} dark /></div></article><aside className="h-fit rounded-2xl border border-border bg-card p-6 lg:sticky lg:top-24"><p className="mono-font text-[10px] uppercase tracking-[.18em] text-primary">Save your seat</p><h2 className="display-font mt-3 text-3xl">Make it part of your week.</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">Registration closes {dateLabel(item.registration_deadline)}.</p>{message && <p className={cx('mt-5 rounded-xl p-3 text-sm', registered ? 'bg-primary/10 text-primary' : 'bg-destructive/10 text-destructive')} data-testid="status-registration-message">{message}</p>}<button disabled={register.isPending || registered || item.status === 'CANCELLED'} onClick={join} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground disabled:opacity-55" data-testid="button-register-event">{register.isPending && <Loader2 className="h-4 w-4 animate-spin" />}{registered ? <><Check className="h-4 w-4" />Registered</> : item.status === 'CANCELLED' ? 'Registration closed' : 'Register for this event'}</button>{!auth.data && <p className="mt-3 text-center text-xs text-muted-foreground">You will need a student profile to register.</p>}</aside></div></div>;
}
function Detail({ icon, label, value, dark = false }: { icon: ReactNode; label: string; value: string; dark?: boolean }) { return <div><div className={cx('flex items-center gap-2 text-xs', dark ? 'text-background/45' : 'text-muted-foreground')}>{icon}{label}</div><p className={cx('mt-2 text-sm font-medium', dark ? 'text-background' : 'text-foreground')}>{value}</p></div>; }

function MyRegistrationsPage() {
  const data = useListMyRegistrations({ query: { queryKey: getListMyRegistrationsQueryKey() } }); const cancel = useCancelRegistration(); const [notice, setNotice] = useState('');
  const doCancel = (id: number) => { if (!window.confirm('Cancel this registration?')) return; cancel.mutate({ id }, { onSuccess: () => { setNotice('Registration cancelled.'); queryClient.invalidateQueries({ queryKey: getListMyRegistrationsQueryKey() }); }, onError: () => setNotice('Could not cancel this registration.') }); };
  if (data.isLoading) return <LoadingBlock label="Finding your registrations" />; if (data.isError) return <ErrorBlock onRetry={() => data.refetch()} />; const registrations = data.data ?? [];
  return <><PageTitle eyebrow="Your participation" title="My registrations" body="The things you said yes to, all in one place." action={<Link href="/events" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground" data-testid="link-find-more">Find more events <ArrowRight className="h-4 w-4" /></Link>} />{notice && <p className="mb-5 rounded-xl bg-primary/10 p-3 text-sm text-primary" data-testid="status-registration-notice">{notice}</p>}{registrations.length ? <div className="grid gap-3">{registrations.map((registration) => <div key={registration.id} className="flex flex-col gap-4 rounded-2xl border border-border bg-card p-5 md:flex-row md:items-center" data-testid={`row-registration-${registration.id}`}><div className="grid h-14 w-14 place-items-center rounded-xl bg-accent/20 text-center"><span className="text-[10px] font-bold uppercase text-accent-foreground">{new Date(`${registration.event.date}T12:00:00`).toLocaleDateString('en-US', { month: 'short' })}</span><span className="display-font text-2xl leading-5">{new Date(`${registration.event.date}T12:00:00`).getDate()}</span></div><div className="min-w-0 flex-1"><Link href={`/events/${registration.event.id}`} className="font-semibold hover:text-primary" data-testid={`link-registration-event-${registration.id}`}>{registration.event.title}</Link><p className="mt-1 text-xs text-muted-foreground">{registration.event.venue} · {timeLabel(registration.event.start_time)} · Registered {dateLabel(registration.registration_date.slice(0, 10))}</p></div><div className="flex items-center gap-3"><Badge tone={registration.status === 'CANCELLED' ? 'red' : registration.status === 'ATTENDED' ? 'teal' : 'amber'}>{registration.status}</Badge>{registration.status === 'REGISTERED' && <button onClick={() => doCancel(registration.id)} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" data-testid={`button-cancel-registration-${registration.id}`}><X className="h-4 w-4" /></button>}</div></div>)}</div> : <EmptyBlock title="Nothing booked yet." body="The best registration is the one that gets you into a room with new people." action={<Link href="/events" className="font-semibold text-primary" data-testid="link-empty-registration-events">Explore events</Link>} />}</>;
}

function ProfilePage() {
  const auth = useAuthUser(); if (auth.isLoading || !auth.data) return <LoadingBlock />; const user = auth.data;
  return <><PageTitle eyebrow="Your profile" title="A little about you." body="Your profile keeps registrations personal and your campus presence easy to find." /><div className="grid gap-6 lg:grid-cols-[.75fr_1.25fr]"><section className="rounded-3xl bg-foreground p-7 text-background"><Avatar user={user} /><h2 className="display-font mt-7 text-4xl">{user.name}</h2><p className="mt-2 text-sm text-background/60">{user.email}</p><Badge tone="teal">{user.role === 'ADMIN' ? 'Coordinator' : 'Student'}</Badge><div className="mt-10 border-t border-background/15 pt-5"><p className="mono-font text-[10px] uppercase tracking-[.18em] text-background/40">Member since</p><p className="mt-2 text-sm">{dateLabel(user.created_at.slice(0, 10))}</p></div></section><section className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center gap-3"><span className="rounded-xl bg-primary/10 p-2 text-primary"><Settings2 className="h-5 w-5" /></span><div><h2 className="font-semibold">Profile details</h2><p className="text-xs text-muted-foreground">Your account is managed securely by CampusPulse.</p></div></div><div className="mt-7 grid gap-5 sm:grid-cols-2"><Detail label="Full name" value={user.name} icon={<UserRound className="h-4 w-4" />} /><Detail label="Email address" value={user.email} icon={<ShieldCheck className="h-4 w-4" />} /><Detail label="Account type" value={user.role === 'ADMIN' ? 'Coordinator' : 'Student'} icon={<Users className="h-4 w-4" />} /><Detail label="Member since" value={dateLabel(user.created_at.slice(0, 10))} icon={<CalendarDays className="h-4 w-4" />} /></div></section></div></>;
}

function EventFormPage({ edit = false }: { edit?: boolean }) {
  const params = useParams<{ id: string }>(); const eventId = Number(params.id); const existing = edit ? useGetEvent(eventId, { query: { queryKey: getGetEventQueryKey(eventId) } }) : undefined; const categories = useListCategories(); const create = useCreateEvent(); const update = useUpdateEvent(); const [, setLocation] = useLocation(); const [error, setError] = useState('');
  const [form, setForm] = useState<EventInput>({ title: '', description: '', category: 0, date: '', start_time: '17:00', end_time: '19:00', venue: '', organizer: '', capacity: 50, registration_deadline: '', status: 'UPCOMING' });
  const [initialized, setInitialized] = useState(false);
  useEffect(() => { if (edit && existing?.data && !initialized) { const item = existing.data; setForm({ title: item.title, description: item.description, category: item.category.id, date: item.date, start_time: item.start_time, end_time: item.end_time, venue: item.venue, organizer: item.organizer, capacity: item.capacity, registration_deadline: dateTimeLocal(item.registration_deadline), status: item.status }); setInitialized(true); } }, [edit, existing?.data, initialized]);
  if (edit && existing?.isLoading) return <LoadingBlock label="Loading event details" />;
  const set = (key: keyof EventInput, value: string | number) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); const data = { ...form, category: Number(form.category), capacity: Number(form.capacity) }; const options = { onSuccess: (saved: Event) => setLocation(`/events/${saved.id}`), onError: () => setError('Please review the form and try again.') }; if (edit) update.mutate({ id: eventId, data }, options); else create.mutate({ data }, options); };
  return <><PageTitle eyebrow={edit ? 'Edit event' : 'New event'} title={edit ? 'Tune the details.' : 'Put something good on.'} body="Give people enough context to make a confident yes." /><form onSubmit={submit} className="max-w-4xl space-y-6"><div className="grid gap-5 rounded-2xl border border-border bg-card p-6 md:grid-cols-2"><div className="md:col-span-2"><Field label="Event title" value={form.title} onChange={(v) => set('title', v)} placeholder="Give it a memorable name" testId="input-event-title" /></div><label className="block space-y-2 md:col-span-2"><span className="text-sm font-semibold">Description</span><textarea required value={form.description} onChange={(e) => set('description', e.target.value)} placeholder="What will people experience?" className="min-h-32 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:border-primary" data-testid="input-event-description" /></label><label className="block space-y-2"><span className="text-sm font-semibold">Category</span><select required value={form.category} onChange={(e) => set('category', Number(e.target.value))} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none focus:border-primary" data-testid="select-form-category"><option value={0}>Choose one</option>{(categories.data ?? []).map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><Field label="Organizer" value={form.organizer} onChange={(v) => set('organizer', v)} placeholder="Team or person" testId="input-event-organizer" /><Field label="Date" type="date" value={form.date} onChange={(v) => set('date', v)} testId="input-event-date" /><Field label="Venue" value={form.venue} onChange={(v) => set('venue', v)} placeholder="Building, room, or online" testId="input-event-venue" /><Field label="Start time" type="time" value={form.start_time} onChange={(v) => set('start_time', v)} testId="input-event-start" /><Field label="End time" type="time" value={form.end_time} onChange={(v) => set('end_time', v)} testId="input-event-end" /><Field label="Capacity" type="number" value={String(form.capacity)} onChange={(v) => set('capacity', Number(v))} placeholder="50" testId="input-event-capacity" /><Field label="Registration deadline" type="datetime-local" value={form.registration_deadline} onChange={(v) => set('registration_deadline', v)} testId="input-event-deadline" /><label className="block space-y-2"><span className="text-sm font-semibold">Status</span><select value={form.status} onChange={(e) => set('status', e.target.value)} className="h-11 w-full rounded-xl border border-input bg-background px-3 text-sm outline-none focus:border-primary" data-testid="select-event-form-status"><option value="UPCOMING">Upcoming</option><option value="ONGOING">Ongoing</option><option value="COMPLETED">Completed</option><option value="CANCELLED">Cancelled</option></select></label></div>{error && <p className="rounded-xl bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="flex gap-3"><button type="button" onClick={() => setLocation('/admin/events')} className="rounded-xl border border-border px-5 py-3 text-sm font-semibold" data-testid="button-cancel-event-form">Cancel</button><button disabled={create.isPending || update.isPending} className="flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground" data-testid="button-save-event">{(create.isPending || update.isPending) && <Loader2 className="h-4 w-4 animate-spin" />}{edit ? 'Save changes' : 'Publish event'}</button></div></form></>;
}

function AdminEventsPage() {
  const events = useListEvents(undefined, { query: { queryKey: getListEventsQueryKey(undefined) } }); const remove = useDeleteEvent(); const [, setLocation] = useLocation();
  const doDelete = (id: number) => { if (!window.confirm('Delete this event?')) return; remove.mutate({ id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListEventsQueryKey(undefined) }) }); };
  return <><PageTitle eyebrow="Workspace / events" title="Event management" body="Publish the moments that give campus its pulse." action={<Link href="/admin/events/new" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground" data-testid="link-create-event"><Plus className="h-4 w-4" />Create event</Link>} />{events.isLoading ? <LoadingBlock /> : events.isError ? <ErrorBlock onRetry={() => events.refetch()} /> : events.data?.length ? <div className="overflow-hidden rounded-2xl border border-border bg-card"><div className="hidden grid-cols-[1.5fr_1fr_.8fr_.7fr_auto] gap-4 border-b border-border bg-muted/50 px-5 py-3 text-[10px] font-bold uppercase tracking-widest text-muted-foreground md:grid"><span>Event</span><span>When</span><span>Attendance</span><span>Status</span><span /></div>{events.data.map((event) => <div key={event.id} className="grid gap-3 border-b border-border p-5 last:border-0 md:grid-cols-[1.5fr_1fr_.8fr_.7fr_auto] md:items-center md:gap-4" data-testid={`row-admin-event-${event.id}`}><div><Link href={`/events/${event.id}`} className="font-semibold hover:text-primary" data-testid={`link-admin-event-${event.id}`}>{event.title}</Link><p className="mt-1 text-xs text-muted-foreground">{event.category.name} · {event.venue}</p></div><p className="text-sm text-muted-foreground">{dateLabel(event.date)}<br /><span className="text-xs">{timeLabel(event.start_time)}</span></p><p className="text-sm"><strong>{event.participant_count}</strong><span className="text-muted-foreground"> / {event.capacity}</span></p><Badge tone={event.status === 'CANCELLED' ? 'red' : event.status === 'COMPLETED' ? 'neutral' : 'teal'}>{event.status}</Badge><div className="flex gap-1"><button onClick={() => setLocation(`/admin/events/${event.id}/edit`)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-primary" data-testid={`button-edit-event-${event.id}`}><Edit3 className="h-4 w-4" /></button><button onClick={() => doDelete(event.id)} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" data-testid={`button-delete-event-${event.id}`}><Trash2 className="h-4 w-4" /></button></div></div>)}</div> : <EmptyBlock title="No events yet." body="Create the first moment on the calendar." action={<Link href="/admin/events/new" className="font-semibold text-primary" data-testid="link-empty-create-event">Create an event</Link>} />}</>;
}

function CategoriesPage() {
  const categories = useListCategories({ query: { queryKey: getListCategoriesQueryKey() } }); const create = useCreateCategory(); const update = useUpdateCategory(); const remove = useDeleteCategory(); const [editing, setEditing] = useState<number | null>(null); const [form, setForm] = useState<CategoryInput>({ name: '', description: '' }); const [error, setError] = useState('');
  const reset = () => { setEditing(null); setForm({ name: '', description: '' }); };
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); const opts = { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListCategoriesQueryKey() }); reset(); }, onError: () => setError('Could not save this category.') }; if (editing) update.mutate({ id: editing, data: form }, opts); else create.mutate({ data: form }, opts); };
  const startEdit = (category: Category) => { setEditing(category.id); setForm({ name: category.name, description: category.description }); };
  const del = (id: number) => { if (!window.confirm('Delete this category?')) return; remove.mutate({ id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListCategoriesQueryKey() }) }); };
  return <><PageTitle eyebrow="Workspace / taxonomy" title="Categories" body="Give people a shared language for finding their kind of thing." /><div className="grid gap-8 lg:grid-cols-[.7fr_1.3fr]"><form onSubmit={submit} className="h-fit rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><h2 className="font-semibold">{editing ? 'Edit category' : 'New category'}</h2>{editing && <button type="button" onClick={reset} className="text-xs text-muted-foreground" data-testid="button-cancel-category">Cancel</button>}</div><div className="mt-5 space-y-4"><Field label="Name" value={form.name} onChange={(v) => setForm({ ...form, name: v })} placeholder="Community & culture" testId="input-category-name" /><label className="block space-y-2"><span className="text-sm font-semibold">Description</span><textarea value={form.description ?? ''} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="What belongs here?" className="min-h-24 w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:border-primary" data-testid="input-category-description" /></label>{error && <p className="text-sm text-destructive">{error}</p>}<button disabled={create.isPending || update.isPending} className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground" data-testid="button-save-category">{(create.isPending || update.isPending) && <Loader2 className="h-4 w-4 animate-spin" />}{editing ? 'Save category' : 'Add category'}</button></div></form><section>{categories.isLoading ? <LoadingBlock /> : categories.isError ? <ErrorBlock onRetry={() => categories.refetch()} /> : categories.data?.length ? <div className="space-y-3">{categories.data.map((category) => <div key={category.id} className="flex items-center gap-4 rounded-2xl border border-border bg-card p-5" data-testid={`row-category-${category.id}`}><span className="grid h-10 w-10 place-items-center rounded-xl bg-accent/20 text-accent-foreground"><Tags className="h-4 w-4" /></span><div className="min-w-0 flex-1"><h3 className="font-semibold">{category.name}</h3><p className="mt-1 truncate text-xs text-muted-foreground">{category.description || 'No description yet.'}</p></div><span className="hidden text-xs text-muted-foreground sm:block">{category.event_count} events</span><button onClick={() => startEdit(category)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-primary" data-testid={`button-edit-category-${category.id}`}><Edit3 className="h-4 w-4" /></button><button onClick={() => del(category.id)} className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive" data-testid={`button-delete-category-${category.id}`}><Trash2 className="h-4 w-4" /></button></div>)}</div> : <EmptyBlock title="Name the moments." body="Categories make discovery feel intuitive." />}</section></div></>;
}

function AdminRegistrationsPage() {
  const data = useListRegistrations({ query: { queryKey: getListRegistrationsQueryKey() } }); const update = useUpdateRegistration(); const [filter, setFilter] = useState('');
  const rows = (data.data ?? []).filter((row) => !filter || row.status === filter);
  const change = (id: number, status: RegistrationStatus) => update.mutate({ id, data: { status } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListRegistrationsQueryKey() }) });
  return <><PageTitle eyebrow="Workspace / people" title="Participant management" body="Keep a clear view of who is joining each event." /><div className="mb-5 flex items-center gap-3"><Filter className="h-4 w-4 text-muted-foreground" /><select value={filter} onChange={(e) => setFilter(e.target.value)} className="rounded-xl border border-input bg-card px-3 py-2 text-sm" data-testid="select-registration-filter"><option value="">All statuses</option><option value="REGISTERED">Registered</option><option value="ATTENDED">Attended</option><option value="ABSENT">Absent</option><option value="CANCELLED">Cancelled</option></select><span className="text-xs text-muted-foreground">{rows.length} records</span></div>{data.isLoading ? <LoadingBlock /> : data.isError ? <ErrorBlock onRetry={() => data.refetch()} /> : rows.length ? <div className="overflow-hidden rounded-2xl border border-border bg-card"><div className="hidden grid-cols-[1.1fr_1.3fr_1fr_.8fr] gap-4 border-b border-border bg-muted/50 px-5 py-3 text-[10px] font-bold uppercase tracking-widest text-muted-foreground md:grid"><span>Student</span><span>Event</span><span>Registered</span><span>Status</span></div>{rows.map((row) => <div key={row.id} className="grid gap-3 border-b border-border p-5 last:border-0 md:grid-cols-[1.1fr_1.3fr_1fr_.8fr] md:items-center md:gap-4" data-testid={`row-registration-admin-${row.id}`}><div className="flex items-center gap-3"><Avatar user={row.student} size="sm" /><div><p className="text-sm font-semibold">{row.student.name}</p><p className="text-xs text-muted-foreground">{row.student.email}</p></div></div><Link href={`/events/${row.event.id}`} className="text-sm font-medium hover:text-primary" data-testid={`link-registration-admin-event-${row.id}`}>{row.event.title}</Link><p className="text-xs text-muted-foreground">{dateLabel(row.registration_date.slice(0, 10))}</p><select value={row.status} onChange={(e) => change(row.id, e.target.value as RegistrationStatus)} className="w-fit rounded-lg border border-input bg-background px-2 py-1.5 text-xs" data-testid={`select-registration-status-${row.id}`}><option value="REGISTERED">Registered</option><option value="ATTENDED">Attended</option><option value="ABSENT">Absent</option><option value="CANCELLED">Cancelled</option></select></div>)}</div> : <EmptyBlock title="No participants yet." body="Registrations will appear here as students join events." />}</>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function NotFoundPage() { return <div className="grid min-h-[100dvh] place-items-center bg-background p-6 text-center"><div><p className="mono-font text-xs uppercase tracking-[.2em] text-primary">404 / off the map</p><h1 className="display-font mt-4 text-6xl">Nothing here yet.</h1><p className="mt-3 text-muted-foreground">This page wandered off campus.</p><Link href="/" className="mt-7 inline-flex rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground" data-testid="link-back-home">Back to CampusPulse</Link></div></div>; }
function Router() { return <RoutedErrorBoundary><Switch><Route path="/" component={PublicLanding} /><Route path="/login" component={LoginPage} /><Route path="/register" component={RegisterPage} /><Route path="/dashboard"><Protected><DashboardPage /></Protected></Route><Route path="/events" component={EventsPage} /><Route path="/events/:id" component={EventDetailsPage} /><Route path="/my-registrations"><Protected><MyRegistrationsPage /></Protected></Route><Route path="/profile"><Protected><ProfilePage /></Protected></Route><Route path="/admin/events/new"><Protected admin><EventFormPage /></Protected></Route><Route path="/admin/events/:id/edit"><Protected admin><EventFormPage edit /></Protected></Route><Route path="/admin/events"><Protected admin><AdminEventsPage /></Protected></Route><Route path="/admin/categories"><Protected admin><CategoriesPage /></Protected></Route><Route path="/admin/registrations"><Protected admin><AdminRegistrationsPage /></Protected></Route><Route component={NotFoundPage} /></Switch></RoutedErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;